// defaultCategory is preselected on the dashboard and the statistics page.
const defaultCategory = "bike"

// maxCompareYears limits the lines in the cumulative year comparison.
const maxCompareYears = 5

// PeriodSummary are the totals of a period compared with the same span one
// year earlier.
type PeriodSummary struct {
	Label    string
	Current  store.Totals
	Previous store.Totals
	// DeltaKm is Current minus Previous distance in km.
	DeltaKm float64
}

// GoalProgress compares the distance so far with a linear yearly goal.
type GoalProgress struct {
	GoalKm     int
	ActualKm   float64
	ExpectedKm float64 // pro-rata goal up to today
	Percent    float64 // of the full-year goal
	AheadKm    float64 // actual − expected
	ForecastKm float64 // linear extrapolation to year end
	Elapsed    bool    // the year is over
}

func categoryFilter(catID string) store.ListFilter {
	var f store.ListFilter
	if _, ok := sport.ByID(catID); ok {
		f.Category = catID
	}
	return f
}

func withRange(f store.ListFilter, from, to time.Time) store.ListFilter {
	f.From, f.To = from, to
	return f
}

// periodSummary sums [from, to) and the same dates one year earlier.
func (s *server) periodSummary(ctx context.Context, label string, base store.ListFilter, from, to time.Time) (PeriodSummary, error) {
	cur, err := s.Store.Totals(ctx, withRange(base, from, to))
	if err != nil {
		return PeriodSummary{}, err
	}
	prev, err := s.Store.Totals(ctx, withRange(base, from.AddDate(-1, 0, 0), to.AddDate(-1, 0, 0)))
	if err != nil {
		return PeriodSummary{}, err
	}
	return PeriodSummary{Label: label, Current: cur, Previous: prev, DeltaKm: (cur.DistanceM - prev.DistanceM) / 1000}, nil
}

// goalProgress evaluates the goal of a category for year as of today.
func (s *server) goalProgress(ctx context.Context, catID string, year int, today time.Time) (*GoalProgress, error) {
	goal, err := s.Store.Goal(ctx, catID)
	if err != nil || goal == 0 {
		return nil, err
	}
	tot, err := s.Store.Totals(ctx, withRange(categoryFilter(catID), yearStart(year), yearStart(year+1)))
	if err != nil {
		return nil, err
	}
	days := float64(daysInYear(year))
	elapsed := days
	if today.Year() == year {
		elapsed = float64(today.YearDay())
	} else if today.Year() < year {
		elapsed = 0
	}
	g := &GoalProgress{GoalKm: goal, ActualKm: tot.DistanceM / 1000, Elapsed: elapsed == days}
	g.ExpectedKm = float64(goal) * elapsed / days
	g.Percent = math.Min(100, 100*g.ActualKm/float64(goal))
	g.AheadKm = g.ActualKm - g.ExpectedKm
	if elapsed > 0 {
		g.ForecastKm = g.ActualKm / elapsed * days
	}
	return g, nil
}

