func (s *server) stats(w http.ResponseWriter, r *http.Request) {
	ctx := r.Context()
	today := localDate(s.now())
	q := r.URL.Query()

	cat, ok := sport.ByID(q.Get("cat"))
	if !ok {
		cat, _ = sport.ByID(defaultCategory)
	}
	years, err := s.Store.Years(ctx)
	if err != nil {
		s.serverError(w, "list years", err)
		return
	}
	year := today.Year()
	if y, err := strconv.Atoi(q.Get("year")); err == nil && y >= 1990 && y <= 2100 {
		year = y
	}
	unit := "month"
	if q.Get("unit") == "week" {
		unit = "week"
	}

	base := categoryFilter(cat.ID)
	d := statsData{Categories: sport.Categories, Category: cat, Years: years, Year: year, Unit: unit, MaxGoal: store.MaxGoalKm}

	// Current year: compare up to today with the same span last year.
	to := yearStart(year + 1)
	label := strconv.Itoa(year)
	if year == today.Year() {
		to = today.AddDate(0, 0, 1)
		label = "bis heute"
	}
	if d.Summary, err = s.periodSummary(ctx, label, base, yearStart(year), to); err != nil {
		s.serverError(w, "sum year", err)
		return
	}
	if d.Goal, err = s.goalProgress(ctx, cat.ID, year, today); err != nil {
		s.serverError(w, "goal", err)
		return
	}
	if d.ByYear, err = s.Store.Aggregate(ctx, base, store.ByYear); err != nil {
		s.serverError(w, "aggregate years", err)
		return
	}
	charts, err := s.chartData(ctx, base, cat.ID, year, unit, today)
	if err != nil {
		s.serverError(w, "chart data", err)
		return
	}
	b, _ := json.Marshal(charts)
	d.Charts = template.JS(b)
	s.render(w, r, "stats.html", "stats", d)
}

