// cumulativeYears returns cumulative distance per day of year for the
// selected year and up to maxCompareYears-1 earlier years with data.
func (s *server) cumulativeYears(ctx context.Context, base store.ListFilter, year int, today time.Time) ([]yearLine, error) {
	first := year - maxCompareYears + 1
	days, err := s.Store.DailyDistance(ctx, withRange(base, yearStart(first), yearStart(year+1)))
	if err != nil {
		return nil, err
	}
	perYear := map[int][]float64{}
	for _, d := range days {
		y := d.Date.Year()
		if perYear[y] == nil {
			perYear[y] = make([]float64, 367)
		}
		perYear[y][d.Date.YearDay()] += d.DistanceM / 1000
	}
	var out []yearLine
	for y := year; y >= first; y-- {
		daily, ok := perYear[y]
		if !ok && y != year {
			continue
		}
		if daily == nil {
			daily = make([]float64, 367)
		}
		n := daysInYear(y)
		last := n
		if y == today.Year() {
			last = today.YearDay()
		} else if y > today.Year() {
			last = 0
		}
		line := yearLine{Year: y, Km: make([]*float64, n)}
		sum := 0.0
		for doy := 1; doy <= n; doy++ {
			sum += daily[doy]
			if doy <= last {
				v := round1(sum)
				line.Km[doy-1] = &v
			}
		}
		out = append(out, line)
	}
	return out, nil
}

func round1(v float64) float64 { return math.Round(v*10) / 10 }

// setGoal stores the yearly goal and asks htmx to reload the page.
func (s *server) setGoal(w http.ResponseWriter, r *http.Request) {
	cat, ok := sport.ByID(r.PostFormValue("cat"))
	if !ok {
		http.Error(w, "unknown category", http.StatusBadRequest)
		return
	}
	km, err := strconv.Atoi(r.PostFormValue("km"))
	if r.PostFormValue("km") == "" {
		km, err = 0, nil
	}
	if err == nil {
		err = s.Store.SetGoal(r.Context(), cat.ID, km)
	}
	if err != nil {
		var numErr *strconv.NumError
		if errors.As(err, &numErr) {
			err = errors.New("bitte eine ganze Zahl eingeben")
		}
		http.Error(w, err.Error(), http.StatusUnprocessableEntity)
		return
	}
	w.Header().Set("HX-Refresh", "true")
	w.WriteHeader(http.StatusNoContent)
}
